import("core.base.json")

local byteorder = import("byteorder", {rootdir = path.join(os.scriptdir(), "..", "..", "..", "modules"), anonymous = true})

local BANNER = [[//
//  %s
//  Generated by tests/backports/callgen/gen-calls.lua from %s
//  and the Objective-C declarations of the SDK's own headers. Do not edit: change the
//  generator and run it again.
//
//  %d classes and %d members are called here. Every class is looked up by name and must
//  exist, every selector is asked for with respondsToSelector: and must answer YES, and
//  every one of them is called with neutral arguments of the type its declaration gives.
//  The calls go through objc_msgSend and not through the declarations, because a call
//  written against the header cannot be missing: the header is what declares it.
//
]]

local PROLOGUE = [[

#import "harness.h"

#import <objc/message.h>
#import <objc/runtime.h>
#include <string.h>

// One case: the label that names it in the report, and the function that performs it. The same
// shape main.m walks, so the generated file and the harness agree on it by construction.
typedef struct {
    const char *label;
    void (*run)(RevenantCallLog *log);
} RevenantCallEntry;
]]

local function each_char(text)
    return text:gmatch("[%z\1-\127\194-\244][\128-\191]*")
end

function mangle(selector)
    local pieces = {}
    for char in each_char(selector) do
        table.insert(pieces, char:match("^[A-Za-z0-9]$") and char or "_")
    end
    local cleaned = table.concat(pieces)
    if cleaned ~= "" and not cleaned:match("^%d") then
        return cleaned
    end
    return "_" .. cleaned
end

local function as_latin1_text(text)
    return (text:gsub("[\128-\255]", function (byte)
        local value = byte:byte()
        return string.char(0xC0 | (value >> 6), 0x80 | (value & 0x3F))
    end))
end

local function c_string(text)
    return (text:gsub("\\", "\\\\"):gsub("\"", "\\\""))
end

local function keywords(selector)
    if not selector:find(":", 1, true) then
        return 0
    end
    local count = 0
    for _ in selector:gmatch(":") do
        count = count + 1
    end
    return count
end

local function sorted_keys(set)
    return byteorder.keys(set or {})
end

local function framework_of(document, folder)
    local named = document.framework
    if type(named) == "string" and named ~= "" then
        return named
    end
    return path.filename(folder)
end

local function json_files(folder)
    local found = {}
    for _, file in ipairs(os.files(path.join(folder, "**.json"))) do
        table.insert(found, file)
    end
    for _, file in ipairs(os.files(path.join(folder, "*.json"))) do
        table.insert(found, file)
    end
    local unique, seen = {}, {}
    for _, file in ipairs(found) do
        if not seen[file] then
            seen[file] = true
            table.insert(unique, file)
        end
    end
    byteorder.sort(unique)
    return unique
end

function read_registry(folders)
    local classes, methods, properties, frameworks = {}, {}, {}, {}
    for _, folder in ipairs(folders) do
        for _, file in ipairs(json_files(folder)) do
            local document = json.decode(io.readfile(file))
            local framework = framework_of(document, path.directory(file))
            frameworks[framework] = true
            for _, entry in ipairs(document.entries or {}) do
                if entry.status == "implemented" then
                    local api, kind = entry.api, entry.kind
                    if kind == "class" then
                        classes[api] = framework
                    elseif kind == "method" then
                        local sign, owner, selector = api:match("^([-+])%[([A-Za-z_0-9]+) (.+)%]$")
                        if sign then
                            methods[owner] = methods[owner] or {}
                            methods[owner][string.format("%s[%s %s]", sign, owner, selector)] = selector
                        end
                    elseif kind == "property" then
                        local owner, name = api, ""
                        local dot = api:find(".", 1, true)
                        if dot then
                            owner, name = api:sub(1, dot - 1), api:sub(dot + 1)
                        end
                        properties[owner] = properties[owner] or {}
                        properties[owner][name] = true
                    end
                end
            end
        end
    end
    return classes, methods, properties, sorted_keys(frameworks)
end

function build_dump(sdk, frameworks, dump)
    local umbrella = dump .. ".umbrella.m"
    local lines = {}
    for _, name in ipairs(frameworks) do
        table.insert(lines, string.format("#import <%s/%s.h>", name, name))
    end
    io.writefile(umbrella, table.concat(lines, "\n") .. "\n")
    local version = path.filename(sdk):gsub("iPhoneOS", ""):gsub("%.sdk", "")
    io.stderr:write("callgen: reading the AST of " .. table.concat(frameworks, ", ") .. "\n")
    os.execv("xcrun", {"clang", "-target", "arm64-apple-ios" .. version, "-isysroot", sdk, "-fsyntax-only", "-x", "objective-c",
                       "-Wno-everything", "-Xclang", "-ast-dump=json", umbrella}, {stdout = dump})
end

local function interface_name(node)
    return type(node.interface) == "table" and node.interface.name or nil
end

function declared_properties(dump, classes, wanted)
    local found = {}
    for name in pairs(classes) do
        found[name] = {}
    end
    local function take(owner, members)
        for _, member in ipairs(members or {}) do
            if member.kind == "ObjCPropertyDecl" and wanted[owner] and wanted[owner][member.name] then
                found[owner][member.name] = member
            end
        end
    end
    local root = json.decode(io.readfile(dump))
    local nodes = root.kind == "TranslationUnitDecl" and (root.inner or {}) or {root}
    for _, node in ipairs(nodes) do
        local kind, name, inner = node.kind, node.name, node.inner
        if kind == "ObjCInterfaceDecl" and inner and #inner > 0 and found[name] then
            take(name, inner)
        elseif kind == "ObjCCategoryDecl" and found[name] then
            local owner = interface_name(node)
            if owner and found[owner] then
                take(owner, inner)
            end
        end
    end
    return found
end

local function emit_class(name)
    return string.format("revenant_case_%s", name), name, {
        string.format("static void revenant_case_%s(RevenantCallLog *log)", name),
        "{",
        string.format("    Class cls = RevenantCallClass(log, @\"%s\");", name),
        "    if (!cls) return;",
        "    RevenantCallNoted(log, cls, @selector(class), cls);",
        "    id instance = RevenantCallInstance(log, cls);",
        "    RevenantCallRemember(log, cls, instance);",
        "}",
        ""
    }
end

local function emit_method(owner, selector, sign)
    local count = keywords(selector)
    local receiver = sign == "-" and "self" or "cls"
    local pointer = "id (*)(id, SEL" .. string.rep(", id", count) .. ")"
    local label = as_latin1_text(string.format("%s[%s %s]", sign, owner, selector))
    local name = string.format("revenant_case_%s_%s_%s", owner, sign == "+" and "class" or "instance", mangle(selector))
    local lines = {
        string.format("static void %s(RevenantCallLog *log)", name),
        "{",
        string.format("    Class cls = RevenantCallClass(log, @\"%s\");", owner),
        "    if (!cls) return;",
        "    @try {"
    }
    if sign == "-" then
        table.insert(lines, "    id self = RevenantCallInstance(log, cls);")
        table.insert(lines, "    if (!self) return;")
        table.insert(lines, string.format("    if (!RevenantCallSelector(log, cls, self, @selector(%s))) return;", selector))
    else
        table.insert(lines, string.format("    if (!RevenantCallSelector(log, cls, cls, @selector(%s))) return;", selector))
    end
    table.insert(lines, string.format("    __unsafe_unretained id value = ((%s)objc_msgSend)(%s, @selector(%s)%s);",
                                      pointer, receiver, selector, string.rep(", nil", count)))
    table.insert(lines, string.format("    RevenantCallNoted(log, cls, @selector(%s), value);", selector))
    table.insert(lines, "    } @catch (NSException *raised) {")
    table.insert(lines, string.format("        RevenantCallRaised(log, cls, @selector(%s), raised);", selector))
    table.insert(lines, "    }")
    table.insert(lines, "}")
    table.insert(lines, "")
    return name, label, lines
end

local function emit_property(owner, name, member)
    local getter = member and type(member.getter) == "table" and member.getter.name or nil
    if not getter or getter == "" then
        getter = name
    end
    local setter = member and type(member.setter) == "table" and member.setter.name or nil
    if setter == "" or (member and member.readonly) then
        setter = nil
    end
    local function_name = string.format("revenant_case_%s_property_%s", owner, mangle(name))
    return function_name, string.format("%s.%s", owner, name), {
        string.format("static void %s(RevenantCallLog *log)", function_name),
        "{",
        string.format("    Class cls = RevenantCallClass(log, @\"%s\");", owner),
        "    if (!cls) return;",
        "    id self = RevenantCallInstance(log, cls);",
        "    if (!self) return;",
        string.format("    RevenantCallProperty(log, cls, self, @\"%s\", @\"%s\", %s);", name, getter,
                      setter and string.format("@\"%s\"", setter) or "nil"),
        "}",
        ""
    }
end

local ESCAPES = {["\""] = "\\\"", ["\\"] = "\\\\", ["\n"] = "\\n", ["\r"] = "\\r", ["\t"] = "\\t", ["\b"] = "\\b", ["\f"] = "\\f"}

local function json_string(text)
    local pieces = {}
    for char in each_char(text) do
        local code = utf8.codepoint(char)
        if ESCAPES[char] then
            table.insert(pieces, ESCAPES[char])
        elseif code < 0x20 or (code > 0x7E and code < 0x10000) then
            table.insert(pieces, string.format("\\u%04x", code))
        elseif code >= 0x10000 then
            code = code - 0x10000
            table.insert(pieces, string.format("\\u%04x\\u%04x", 0xD800 | (code >> 10), 0xDC00 | (code & 0x3FF)))
        else
            table.insert(pieces, char)
        end
    end
    return "\"" .. table.concat(pieces) .. "\""
end

local function manifest_text(manifest)
    local function list(values)
        if #values == 0 then
            return "[]"
        end
        local items = {}
        for _, value in ipairs(values) do
            table.insert(items, "  " .. json_string(value))
        end
        return "[\n" .. table.concat(items, ",\n") .. "\n ]"
    end
    return "{\n \"classes\": " .. list(manifest.classes) .. ",\n \"members\": " .. list(manifest.members) .. "\n}\n"
end

function generate(opt)
    local classes, methods, properties, frameworks = read_registry(opt.registries)
    if not os.isfile(opt.dump) then
        build_dump(opt.sdk, frameworks, opt.dump)
    end
    local declared = declared_properties(opt.dump, classes, properties)
    local manifest = {classes = {}, members = {}}
    local out = {}
    local entries = {}
    local function add(function_name, label, lines)
        for _, line in ipairs(lines) do
            table.insert(out, line)
        end
        table.insert(entries, {label, function_name})
    end
    for _, name in ipairs(sorted_keys(classes)) do
        table.insert(manifest.classes, name)
        add(emit_class(name))
        for _, label in ipairs(sorted_keys(methods[name])) do
            local selector = methods[name][label]
            add(emit_method(name, selector, label:sub(1, 1)))
            table.insert(manifest.members, label)
        end
        for _, property in ipairs(sorted_keys(properties[name])) do
            add(emit_property(name, property, declared[name][property]))
            table.insert(manifest.members, string.format("%s.%s", name, property))
        end
    end
    local text = {string.format(BANNER, path.filename(opt.out), table.concat(opt.registries, ", "),
                                #manifest.classes, #manifest.members), PROLOGUE}
    for _, line in ipairs(out) do
        table.insert(text, line)
    end
    table.insert(text, "const RevenantCallEntry revenant_call_cases[] = {")
    for _, entry in ipairs(entries) do
        table.insert(text, string.format("    { \"%s\", %s },", c_string(entry[1]), entry[2]))
    end
    table.insert(text, "    { NULL, NULL }")
    table.insert(text, "};")
    table.insert(text, string.format("const unsigned revenant_call_case_count = %d;", #entries))
    io.writefile(opt.out, table.concat(text, "\n") .. "\n")
    io.writefile(opt.manifest, manifest_text(manifest))
    return {classes = #manifest.classes, members = #manifest.members, out = opt.out, manifest = opt.manifest}
end

local function parse(arguments)
    local opt = {registries = {}}
    local names = {["--sdk"] = "sdk", ["--dump"] = "dump", ["--out"] = "out", ["--manifest"] = "manifest", ["--registry"] = "registry"}
    local index = 1
    while index <= #arguments do
        local argument = arguments[index]
        local flag, value = argument:match("^(%-%-[%w]+)=(.*)$")
        if not flag then
            flag, value = argument, arguments[index + 1]
            index = index + 1
        end
        local key = names[flag]
        if not key or value == nil then
            raise("usage: xmake l gen-calls.lua --sdk <iPhoneOS*.sdk> --registry <dir>... --dump <ast.json> --out <Calls.m> --manifest <calls.json>")
        end
        if key == "registry" then
            table.insert(opt.registries, value)
        else
            opt[key] = value
        end
        index = index + 1
    end
    for _, key in ipairs({"sdk", "dump", "out", "manifest"}) do
        if not opt[key] then
            raise("gen-calls.lua: --%s is required", key)
        end
    end
    if #opt.registries == 0 then
        raise("gen-calls.lua: --registry is required")
    end
    return opt
end

function main(...)
    local result = generate(parse({...}))
    print(string.format("%s: %d classes, %d members called", result.out, result.classes, result.members))
end
